export function getAllTemplates(): TemplateDefinition[] {
  return [...BUILTIN_TEMPLATES];
}

export function getTemplateById(id: string): TemplateDefinition | undefined {
  return BUILTIN_TEMPLATES.find((t) => t.manifest.id === id);
}

export function getTemplatesByCategory(category: TemplateCategory): TemplateDefinition[] {
  return BUILTIN_TEMPLATES.filter((t) => t.manifest.category === category);
}

export function getTemplatesByAspect(aspect: AspectRatio): TemplateDefinition[] {
  return BUILTIN_TEMPLATES.filter((t) => t.manifest.aspect === aspect);
}

export function getTrendingTemplates(): TemplateDefinition[] {
  const trendingIds = new Set([
    'apple-bento-launch',
    'xhs-swiss-grid',
    'xhs-neon-tech',
    'poster-risograph',
    'apple-dark-keynote',
    'ppt-linear-dark',
  ]);
  return BUILTIN_TEMPLATES.filter((t) => trendingIds.has(t.manifest.id));
}

export function getTemplateSampleDeck(id: string): string | undefined {
  const t = getTemplateById(id);
  return t?.sampleDeckMd;
}

export function validateTemplateManifest(manifest: any): { valid: boolean; errors: string[] } {
  const errors: string[] = [];
  if (!manifest || typeof manifest !== 'object') {
    return { valid: false, errors: ['Manifest must be a non-null object'] };
  }
  if (!manifest.id || typeof manifest.id !== 'string') {
    errors.push('Manifest missing valid string id');
  }
  if (!manifest.name || typeof manifest.name !== 'object' || !manifest.name.zh || !manifest.name.en) {
    errors.push('Manifest missing localized name with at least zh and en');
  }
  if (!manifest.description || typeof manifest.description !== 'object') {
    errors.push('Manifest missing localized description');
  }
  if (!manifest.category) {
    errors.push('Manifest missing category');
  }
  if (!manifest.aspect) {
    errors.push('Manifest missing aspect ratio');
  }
  if (!manifest.width || !manifest.height) {
    errors.push('Manifest missing width or height');
  }
  if (!Array.isArray(manifest.supportedFormats) || manifest.supportedFormats.length === 0) {
    errors.push('Manifest missing supportedFormats array');
  }
  return { valid: errors.length === 0, errors };
}

export function validateTemplateHtml(html: string): { valid: boolean; errors: string[] } {
  const errors: string[] = [];
  if (typeof html !== 'string' || html.length === 0) {
    return { valid: false, errors: ['HTML content cannot be empty'] };
  }
  if (!html.includes('window.renderDeck')) {
    errors.push('Missing required window.renderDeck contract');
  }
  if (!html.includes('data-editable')) {
    errors.push('Missing required data-editable annotations');
  }
  if (!html.includes('fitStage')) {
    errors.push('Missing required fitStage function');
  }
  if (!html.includes('--bg') || !html.includes('--ink') || !html.includes('--accent')) {
    errors.push('Missing fundamental CSS variables (--bg, --ink, --accent)');
  }
  if (!html.includes('data-theme="dark"') || !html.includes('data-theme="light"')) {
    errors.push('Missing explicit data-theme dark and light selector support');
  }
  return { valid: errors.length === 0, errors };
}
